/* @autogenerated */
package net.civeira.phylax.feature.observe.probe;

import java.net.URI;
import java.net.http.HttpClient;
import java.time.Duration;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import io.quarkus.arc.Arc;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.transaction.Transactional;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.metric.ObserveMetrics;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbeLastStatusOptions;
import net.civeira.phylax.feature.observe.observedprobe.domain.gateway.ObservedProbeCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observedprobe.domain.gateway.ObservedProbeFilter;
import net.civeira.phylax.feature.observe.source.SourceRegistry;

/**
 * Runs the enabled probes: every 10 seconds it looks which ones are due and checks them in a small
 * pool (never in the ingestion threads). Each result is saved in the probe (record-check), kept in
 * memory for the alerts and the viewer, and counted in the metrics of its origin as method PROBE,
 * so the availability and the latency history come from the same store.
 *
 * <p>
 * With several replicas only one should run them: {@code app.observe.probes.enabled=false} in the
 * others.
 */
@ApplicationScoped
@Slf4j
public class ProbeRunner {

  public static final String METHOD = "PROBE";
  private static final int MIN_INTERVAL = 30;

  /** State of a probe after its last check. */
  public record ProbeState(String uid, String name, String originUid, String source, String url,
      boolean up, long checkedAt, long latencyMs, int failures, String error, Long tlsExpiresAt,
      int failuresToAlert, int tlsWarnDays) {}

  private final ObservedProbeCommandRepositoryGateway probes;
  private final ObserveMetrics metrics;
  private final SourceRegistry registry;
  private final boolean enabled;
  private final Set<String> configuredHosts;
  private final String publicUrl;
  private final String selfSource;
  private final HttpClient http = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5))
      .followRedirects(HttpClient.Redirect.NEVER).build();
  private final Map<String, ProbeState> states = new ConcurrentHashMap<>();
  private final Map<String, Long> running = new ConcurrentHashMap<>();
  private ScheduledExecutorService scheduler;
  private ExecutorService pool;

  public ProbeRunner(final ObservedProbeCommandRepositoryGateway probes,
      final ObserveMetrics metrics, final SourceRegistry registry,
      final @ConfigProperty(name = "app.observe.probes.enabled",
          defaultValue = "true") boolean enabled,
      final @ConfigProperty(
          name = "app.observe.probes.allowed-hosts") Optional<String> allowedHosts,
      final @ConfigProperty(name = "app.observe.public-url") Optional<String> publicUrl,
      final @ConfigProperty(name = "app.observe.self-source",
          defaultValue = "phylax-api") String selfSource) {
    this.probes = probes;
    this.metrics = metrics;
    this.registry = registry;
    this.enabled = enabled;
    this.configuredHosts = hosts(allowedHosts.orElse(""));
    this.publicUrl = publicUrl.orElse("");
    this.selfSource = selfSource;
  }

  public List<ProbeState> states() {
    return List.copyOf(states.values());
  }

  /** The probes for the viewer: last state plus availability and p95 of 7 and 30 days. */
  public List<Map<String, Object>> view() {
    long now = System.currentTimeMillis();
    long day = 86_400_000L;
    List<Map<String, Object>> rows = new java.util.ArrayList<>();
    for (ProbeState state : states.values()) {
      var points = metrics.raw(Set.of(state.source()), now - 30 * day, now, true).stream()
          .filter(
              p -> net.civeira.phylax.feature.observe.metric.MetricDeriver.PROBE.equals(p.method())
                  && ("probe " + state.name()).equals(p.route()))
          .toList();
      Map<String, Object> row = new java.util.LinkedHashMap<>();
      row.put("uid", state.uid());
      row.put("name", state.name());
      row.put("source", state.source());
      row.put("url", state.url());
      row.put("up", state.up());
      row.put("checkedAt", state.checkedAt());
      row.put("latencyMs", state.latencyMs());
      row.put("failures", state.failures());
      row.put("error", state.error());
      row.put("tlsExpiresAt", state.tlsExpiresAt());
      row.put("availability7d", availability(points, now - 7 * day));
      row.put("availability30d", availability(points, now - 30 * day));
      rows.add(row);
    }
    rows.sort((a, b) -> String.valueOf(a.get("name")).compareTo(String.valueOf(b.get("name"))));
    return rows;
  }

  /**
   * Share of good checks since {@code from}, in per cent with two decimals (null without checks).
   */
  static Double availability(
      final List<net.civeira.phylax.feature.observe.metric.MetricPoint> points, final long from) {
    long total = 0;
    long failed = 0;
    for (var point : points) {
      if (point.ts() >= from) {
        total += point.count();
        failed += point.errors();
      }
    }
    return total == 0 ? null : Math.round(10_000.0 * (total - failed) / total) / 100.0;
  }

  public void start() {
    if (!enabled || null != scheduler) {
      return;
    }
    pool = Executors.newFixedThreadPool(4, r -> {
      Thread thread = new Thread(r, "observe-probe");
      thread.setDaemon(true);
      return thread;
    });
    scheduler = Executors.newSingleThreadScheduledExecutor(r -> {
      Thread thread = new Thread(r, "observe-probes");
      thread.setDaemon(true);
      return thread;
    });
    scheduler.scheduleWithFixedDelay(this::tickQuietly, 15, 10, TimeUnit.SECONDS);
  }

  public void stop() {
    if (null != scheduler) {
      scheduler.shutdownNow();
      pool.shutdownNow();
    }
  }

  /**
   * Hosts that can be called: {@code app.observe.probes.allowed-hosts} or, when empty, the hosts of
   * the public url and of the allowed-origins of the sources (the applications we observe).
   */
  public Set<String> allowedHosts() {
    if (!configuredHosts.isEmpty()) {
      return configuredHosts;
    }
    Set<String> result = new HashSet<>();
    addHost(result, publicUrl);
    for (SourceRegistry.Source source : registry.all()) {
      source.allowedOrigins().forEach(origin -> addHost(result, origin));
    }
    return result;
  }

  private void tickQuietly() {
    try {
      long now = System.currentTimeMillis();
      for (ObservedProbe probe : inRequest(() -> self().enabled())) {
        int interval = Math.max(MIN_INTERVAL,
            null == probe.getIntervalSeconds() ? 60 : probe.getIntervalSeconds());
        ProbeState last = states.get(probe.getUid());
        boolean due = null == last || now - last.checkedAt() >= interval * 1000L;
        if (due && null == running.putIfAbsent(probe.getUid(), now)) {
          pool.submit(() -> check(probe));
        }
      }
    } catch (RuntimeException ex) {
      log.warn("Unable to run the probes: {}", ex.getMessage());
    }
  }

  private void check(final ObservedProbe probe) {
    try {
      ProbeCheck.Result result = ProbeCheck.run(http,
          new ProbeCheck.Target(probe.getUrl(),
              null == probe.getMethod() ? "get" : probe.getMethod().name(),
              null == probe.getExpectedStatus() ? 200 : probe.getExpectedStatus(),
              probe.getExpectedText().orElse(null),
              null == probe.getTimeoutMs() ? 5000 : probe.getTimeoutMs()),
          allowedHosts());
      ProbeState previous = states.get(probe.getUid());
      int failures = result.up() ? 0 : (null == previous ? 0 : previous.failures()) + 1;
      long now = System.currentTimeMillis();
      String source = sourceOf(probe.getOriginUid().orElse(null));
      ProbeState state = new ProbeState(probe.getUid(), probe.getName(),
          probe.getOriginUid().orElse(null), source, probe.getUrl(), result.up(), now,
          result.latencyMs(), failures, result.error(), result.tlsExpiresAt(),
          null == probe.getFailuresToAlert() ? 2 : probe.getFailuresToAlert(),
          null == probe.getTlsWarnDays() ? 14 : probe.getTlsWarnDays());
      states.put(probe.getUid(), state);
      metrics.recordProbe(source, probe.getName(), now, result.latencyMs(), !result.up());
      inRequest(() -> {
        self().save(state);
        return null;
      });
    } catch (RuntimeException ex) {
      log.warn("Unable to check the probe {}: {}", probe.getName(), ex.getMessage());
    } finally {
      running.remove(probe.getUid());
    }
  }

  @Transactional
  public List<ObservedProbe> enabled() {
    return probes.list(ObservedProbeFilter.builder().build()).stream()
        .filter(probe -> Boolean.TRUE.equals(probe.isEnabled())).toList();
  }

  @Transactional
  public void save(final ProbeState state) {
    probes.find(ObservedProbeFilter.builder().uid(state.uid()).build())
        .ifPresent(row -> probes.update(row,
            row.recordCheck(
                state.up() ? ObservedProbeLastStatusOptions.UP
                    : ObservedProbeLastStatusOptions.DOWN,
                time(state.checkedAt()), (int) Math.min(Integer.MAX_VALUE, state.latencyMs()),
                state.failures(), null == state.error() ? "" : truncate(state.error()),
                null == state.tlsExpiresAt() ? null : time(state.tlsExpiresAt()))));
  }

  private String sourceOf(final String originUid) {
    if (null == originUid) {
      return selfSource;
    }
    return registry.all().stream().filter(source -> originUid.equals(source.uid()))
        .map(SourceRegistry.Source::code).findFirst().orElse(selfSource);
  }

  private static String truncate(final String value) {
    return value.length() > 250 ? value.substring(0, 249) + "…" : value;
  }

  private static OffsetDateTime time(final long millis) {
    return OffsetDateTime.ofInstant(Instant.ofEpochMilli(millis), ZoneOffset.UTC);
  }

  static Set<String> hosts(final String value) {
    Set<String> result = new HashSet<>();
    Arrays.stream(value.split(",")).map(String::trim).filter(v -> !v.isEmpty())
        .map(v -> v.toLowerCase(Locale.ROOT)).forEach(result::add);
    return result;
  }

  private static void addHost(final Set<String> hosts, final String url) {
    try {
      String host = null == url || url.isBlank() ? null : URI.create(url.trim()).getHost();
      if (null != host) {
        hosts.add(host.toLowerCase(Locale.ROOT));
      }
    } catch (IllegalArgumentException ex) {
      // Not a URL: ignored
    }
  }

  private ProbeRunner self() {
    return Arc.container().instance(ProbeRunner.class).get();
  }

  private static <T> T inRequest(final java.util.function.Supplier<T> work) {
    boolean activated = !Arc.container().requestContext().isActive();
    if (activated) {
      Arc.container().requestContext().activate();
    }
    try {
      return work.get();
    } finally {
      if (activated) {
        Arc.container().requestContext().terminate();
      }
    }
  }
}
